package hu.bankmonitor.payments;

import hu.bankmonitor.testsupport.ThreadProbeController;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.web.server.LocalServerPort;
import org.springframework.context.annotation.Import;
import org.springframework.test.web.servlet.client.RestTestClient;

/**
 * The application starts on H2 and answers over real HTTP.
 *
 * <p>Runs on a real servlet container ({@code RANDOM_PORT}) rather than MockMvc, because
 * both claims under test are about the container: that an HTTP request reaches a
 * listening port at all, and what kind of thread Tomcat serves it on. MockMvc would
 * bypass the container and prove neither.
 *
 * <p>Shares its application context with {@code OpenApiDocumentSpikeTest} -- the two
 * classes carry identical configuration on purpose, so Spring's context cache boots the
 * application once for both instead of twice.
 */
@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
@Import(ThreadProbeController.class)
class ApplicationBootsTest {

	@LocalServerPort
	private int port;

	private RestTestClient client() {
		// TestRestTemplate is gone in Spring Boot 4. RestTestClient, new in Spring
		// Framework 7, is the replacement -- worth noting because every tutorial still
		// reaches for the old one.
		return RestTestClient.bindToServer().baseUrl("http://localhost:" + port).build();
	}

	@Test
	@DisplayName("the health endpoint reports UP")
	void healthEndpointReportsUp() {
		client().get().uri("/actuator/health")
				.exchange()
				.expectStatus().isOk()
				.expectBody()
				.jsonPath("$.status").isEqualTo("UP")
				// The datasource is part of the health aggregate, so an UP overall status
				// also says H2 was reachable rather than merely configured.
				.jsonPath("$.components.db.status").isEqualTo("UP");
	}

	@Test
	@DisplayName("requests are served on virtual threads")
	void servesRequestsOnVirtualThreads() {
		// The setting `spring.threads.virtual.enabled=true` is load-bearing rather than a
		// nicety: the stand-in Exchange Rate provider is a real HTTP endpoint inside this
		// same application, so serving a transfer means one request thread waits on a
		// second thread of this same server. Asserting the property is set would only
		// restate the configuration file; asking the container what it actually did is
		// the claim worth testing.
		client().get().uri(ThreadProbeController.PATH)
				.exchange()
				.expectStatus().isOk()
				.expectBody()
				.jsonPath("$.virtual").isEqualTo(true);
	}
}

